function validate([n]) {
  if (!Number.isInteger(n) || n < 2 || n > 100000) return 'n is an integer from 2 to 100000.';
  return null;
}

reference:
function smallestValue(n) {
  while (true) {
    let sum = 0;
    let rest = n;
    for (let factor = 2; factor * factor <= rest; factor++) {
      while (rest % factor === 0) {
        sum += factor;
        rest /= factor;
      }
    }
    if (rest > 1) {
      sum += rest;
    }
    if (sum === n) {
      return n;
    }
    n = sum;
  }
}

brute:
function smallestValue(n) {
  const seen = new Set();
  let best = n;
  while (!seen.has(n)) {
    seen.add(n);
    best = Math.min(best, n);
    let total = 0, x = n;
    for (let d = 2; d <= x; d++) while (x % d === 0) { total += d; x /= d; }
    n = total;
  }
  return best;
}

generator:
function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') return [pick(50000, 100000)];
  const r = rand();
  if (r < 0.15) return [2 ** pick(1, 16)];
  if (r < 0.3) return [pick(2, 12)];
  return [pick(2, 1000)];
}
